<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
type User={id:number,full_name:string,login:string,role:string}
type Category={id:number,name:string}
type Product={id:number,name:string,category_id:number,category:string,price:string,is_active:boolean}
type Employee={id:number,full_name:string,login:string,role_id:number,role:string,is_active:boolean}
type Order={id:number,created_at:string,status:string,items:{name:string,quantity:number}[]}
const token=ref(sessionStorage.getItem('token')||''); const user=ref<User|null>(null); const error=ref(''); const login=ref(''); const password=ref(''); const page=ref(''); const categories=ref<Category[]>([]); const products=ref<Product[]>([]); const employees=ref<Employee[]>([]); const roles=ref<{id:number,code:string}[]>([]); const orders=ref<Order[]>([]); const delivered=ref(0); const filter=ref(0); const cart=ref<Record<number,number>>({}); const receipt=ref<any>(null); const day=ref(new Date().toLocaleDateString('sv-SE')); const report=ref<any>({summary:{orders_count:0,revenue:0},items:[]}); const editProduct=ref<any>(null); const editEmployee=ref<any>(null); const categoryName=ref(''); const showCategories=ref(false)
const money=(n:any)=>Number(n||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})
async function api(path:string,options:RequestInit={}){const res=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...options.headers}}); if(!res.ok){let data=await res.json().catch(()=>({})); if(res.status===401&&path!='/login') logout(); throw new Error(typeof data.detail==='string'?data.detail:'Проверьте введённые данные')} return res.json()}
async function run(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения'}}
function logout(){token.value='';sessionStorage.removeItem('token');user.value=null;cart.value={};receipt.value=null;error.value=''}
async function signIn(){await run(async()=>{const data=await api('/login',{method:'POST',body:JSON.stringify({login:login.value,password:password.value})});token.value=data.token;sessionStorage.setItem('token',data.token);user.value=data.user;password.value='';await init()})}
async function init(){if(!user.value)return;page.value=user.value.role==='Администратор'?'Меню':user.value.role==='Повар'?'Очередь':'Новый заказ'; await refresh()}
async function refresh(){if(!user.value)return; if(user.value.role==='Кассир'||user.value.role==='Администратор'){[products.value,categories.value]=await Promise.all([api('/menu'),api('/categories')])} if(user.value.role==='Повар'){const data=await api('/orders');orders.value=data.orders;delivered.value=data.delivered} if(user.value.role==='Администратор'){[employees.value,roles.value]=await Promise.all([api('/employees'),api('/roles')]);await loadReport()}}
async function loadReport(){if(user.value?.role==='Администратор')report.value=await api('/report?day='+day.value)}
watch(day,()=>run(loadReport)); let timer:number|undefined
onMounted(()=>{if(token.value)run(async()=>{user.value=await api('/me');await init()});timer=window.setInterval(()=>{if(user.value?.role==='Повар')run(refresh)},15000)});onUnmounted(()=>clearInterval(timer))
const visibleProducts=computed(()=>products.value.filter(p=>!filter.value||p.category_id===filter.value));const cartItems=computed(()=>products.value.filter(p=>cart.value[p.id]>0));const total=computed(()=>cartItems.value.reduce((n,p)=>n+Number(p.price)*cart.value[p.id],0))
function change(id:number,delta:number){const n=(cart.value[id]||0)+delta;if(n<=0)delete cart.value[id];else cart.value[id]=n}
async function checkout(){await run(async()=>{receipt.value=await api('/orders',{method:'POST',body:JSON.stringify({items:cartItems.value.map(p=>({menu_item_id:p.id,quantity:cart.value[p.id]}))})});cart.value={}})}
async function advance(o:Order){await run(async()=>{await api('/orders/'+o.id,{method:'PATCH',body:JSON.stringify({status:o.status==='Принят'?'Готовится':'Выдан'})});await refresh()})}
function productForm(p?:Product){editProduct.value=p?{...p}:{name:'',category_id:categories.value[0]?.id,price:0,is_active:true}}
async function saveProduct(){await run(async()=>{const p=editProduct.value;await api('/menu'+(p.id?'/'+p.id:''),{method:p.id?'PUT':'POST',body:JSON.stringify(p)});editProduct.value=null;await refresh()})}
async function addCategory(){await run(async()=>{await api('/categories',{method:'POST',body:JSON.stringify({name:categoryName.value})});categoryName.value='';await refresh()})}
function employeeForm(e?:Employee){editEmployee.value=e?{...e,password:''}:{full_name:'',login:'',role_id:1,password:'',is_active:true}}
async function saveEmployee(){await run(async()=>{const e={...editEmployee.value};if(!e.password)e.password=null;await api('/employees'+(e.id?'/'+e.id:''),{method:e.id?'PUT':'POST',body:JSON.stringify(e)});editEmployee.value=null;await refresh()})}
function picture(name:string){const n=name.toLowerCase();return n.includes('круассан')?'croissant':n.includes('кориц')?'cinnamon':n.includes('пирог')?'pie':n.includes('наполеон')?'cake':n.includes('чизкейк')?'cheesecake':n.includes('кофе')||n.includes('капучино')||n.includes('эспрессо')?'coffee':'croissant'}
function age(s:string){const minutes=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return minutes<60?`${minutes} мин назад`:new Date(s).toLocaleString('ru-RU')}
</script>
<template>
<div v-if="!user" class="login-layout"><section class="welcome"><div><h1>Пшеница и огонь</h1><p>Свежая выпечка каждый день</p><div class="welcome-grid"><img v-for="pic in ['croissant','cinnamon','cheesecake','coffee','cake','pie']" :key="pic" :src="'/'+pic+'.png'" alt=""></div></div></section><section class="login-side"><form class="panel login-box" @submit.prevent="signIn"><h1>Вход в систему</h1><label>Логин<input v-model="login" autocomplete="username" required></label><label>Пароль<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary full">Войти</button><p class="muted">После входа откроется экран вашей роли.</p></form></section></div>
<template v-else><header><div class="brand">Пшеница и огонь</div><nav><button v-for="tab in (user.role==='Администратор'?['Меню','Отчёты','Сотрудники']:user.role==='Повар'?['Очередь']:['Новый заказ'])" :key="tab" :class="{selected:page===tab}" @click="page=tab;receipt=null">{{tab}}</button></nav><div class="identity">{{user.full_name}} · {{user.role}}</div><button @click="logout">Выйти</button></header><main><div v-if="error" class="error alert" role="alert">{{error}} <button @click="error=''">×</button></div>
<template v-if="user.role==='Кассир'"><div v-if="!receipt" class="cash-layout"><section class="panel"><div class="filters"><button :class="{active:filter===0}" @click="filter=0">Все</button><button v-for="c in categories" :key="c.id" :class="{active:filter===c.id}" @click="filter=c.id">{{c.name}}</button></div><div class="products"><article v-for="p in visibleProducts" :key="p.id" class="product"><img :src="'/'+picture(p.name)+'.png'" alt=""><div><span><strong>{{p.name}}</strong><small>{{money(p.price)}}</small></span><button class="add" :aria-label="'Добавить '+p.name" @click="change(p.id,1)">+</button></div></article></div></section><aside class="panel cart"><div><div class="row"><h1>Новый заказ</h1><span class="badge">новый</span></div><p v-if="!cartItems.length" class="muted empty">Корзина пуста<br>Добавьте позиции из меню</p><div v-for="p in cartItems" :key="p.id" class="cart-line"><img :src="'/'+picture(p.name)+'.png'" alt=""><span>{{p.name}}</span><button @click="change(p.id,-1)">−</button><b>{{cart[p.id]}}</b><button @click="change(p.id,1)">+</button><b>{{money(Number(p.price)*cart[p.id])}}</b></div></div><div><div class="row total"><strong>Итого</strong><strong>{{money(total)}}</strong></div><button class="primary full" :disabled="!cartItems.length" @click="checkout">Оформить заказ</button><button class="full" @click="cart={}">Очистить</button></div></aside></div><section v-else class="panel receipt"><h1>Заказ № {{receipt.id}}</h1><p class="muted">Заказ оформлен</p><div v-for="item in receipt.items" :key="item.name" class="row receipt-line"><span>{{item.name}} × {{item.quantity}}</span><b>{{money(Number(item.unit_price)*item.quantity)}}</b></div><div class="row total"><strong>Итого</strong><strong>{{money(receipt.total)}}</strong></div><button class="primary full" @click="receipt=null">Новый заказ</button></section></template>
<template v-else-if="user.role==='Повар'"><div class="queue"><section v-for="status in ['Принят','Готовится']" :key="status"><h1>{{status}} <span class="badge" :class="{blue:status==='Готовится'}">{{orders.filter(o=>o.status===status).length}}</span></h1><article v-for="o in orders.filter(o=>o.status===status)" :key="o.id" class="panel order"><div class="row"><strong>Заказ № {{o.id}}</strong><span class="muted">{{age(o.created_at)}}</span></div><div v-for="item in o.items" :key="item.name" class="order-item"><img :src="'/'+picture(item.name)+'.png'" alt="">{{item.name}} × {{item.quantity}}</div><button class="primary full" @click="advance(o)">{{status==='Принят'?'Взять в работу':'Выдан'}}</button></article><p v-if="!orders.some(o=>o.status===status)" class="muted">Заказов пока нет</p></section><aside class="panel stat"><span class="muted">Выдано сегодня</span><strong>{{delivered}}</strong></aside></div></template>
<template v-else><section v-if="page==='Меню'" class="panel"><div class="row title"><h1>Меню</h1><div><button @click="showCategories=!showCategories">Категории</button> <button class="primary" @click="productForm()">Добавить позицию</button></div></div><form v-if="showCategories" class="inline" @submit.prevent="addCategory"><input v-model="categoryName" placeholder="Новая категория" required><button>Добавить категорию</button></form><div class="table-wrap"><table><thead><tr><th>Позиция</th><th>Категория</th><th>Цена</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><div class="item-name"><img :src="'/'+picture(p.name)+'.png'" alt="">{{p.name}}</div></td><td>{{p.category}}</td><td>{{money(p.price)}}</td><td><span class="badge" :class="p.is_active?'green':'grey'">{{p.is_active?'В меню':'Скрыта'}}</span></td><td><button class="link" @click="productForm(p)">Изменить</button></td></tr></tbody></table></div></section>
<template v-else-if="page==='Отчёты'"><div class="row title"><h1>Продажи за день</h1><label class="inline">Дата <input v-model="day" type="date"></label></div><div class="stats"><div class="panel stat"><span class="muted">Выручка</span><strong>{{money(report.summary.revenue)}}</strong></div><div class="panel stat"><span class="muted">Заказов</span><strong>{{report.summary.orders_count}}</strong></div><div class="panel stat"><span class="muted">Средний чек</span><strong>{{money(report.summary.orders_count?Number(report.summary.revenue)/report.summary.orders_count:0)}}</strong></div></div><section class="panel"><h2>По позициям</h2><table><thead><tr><th>Позиция</th><th>Продано, шт</th><th>Выручка</th></tr></thead><tbody><tr v-for="i in report.items" :key="i.item_name"><td>{{i.item_name}}</td><td>{{i.qty_sold}}</td><td>{{money(i.revenue)}}</td></tr></tbody></table><p v-if="!report.items.length" class="muted">За выбранный день продаж нет.</p></section></template>
<div v-else class="staff-layout"><section class="panel"><h2>Сотрудники</h2><div class="table-wrap"><table><thead><tr><th>ФИО</th><th>Логин</th><th>Роль</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="e in employees" :key="e.id"><td>{{e.full_name}}</td><td>{{e.login}}</td><td>{{e.role}}</td><td><span class="badge" :class="e.is_active?'green':'grey'">{{e.is_active?'Активен':'Отключён'}}</span></td><td><button class="link" @click="employeeForm(e)">Изменить</button></td></tr></tbody></table></div></section><section class="panel"><h2>{{editEmployee?.id?'Изменить сотрудника':'Новый сотрудник'}}</h2><button v-if="!editEmployee" class="primary full" @click="employeeForm()">Добавить сотрудника</button><form v-else @submit.prevent="saveEmployee"><label>ФИО<input v-model="editEmployee.full_name" required maxlength="100"></label><label>Логин<input v-model="editEmployee.login" required maxlength="50"></label><label>Роль<select v-model="editEmployee.role_id"><option v-for="r in roles" :key="r.id" :value="r.id">{{r.code}}</option></select></label><label>{{editEmployee.id?'Новый пароль (необязательно)':'Пароль'}}<input v-model="editEmployee.password" type="password" :required="!editEmployee.id" minlength="8"></label><label class="check"><input v-model="editEmployee.is_active" type="checkbox"> Активен</label><button class="primary full">Сохранить</button><button class="full" type="button" @click="editEmployee=null">Отмена</button></form></section></div></template>
</main><div v-if="editProduct" class="overlay"><form class="panel modal" @submit.prevent="saveProduct"><h2>{{editProduct.id?'Изменить позицию':'Добавить позицию'}}</h2><label>Название<input v-model="editProduct.name" required maxlength="150"></label><label>Категория<select v-model="editProduct.category_id"><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Цена<input v-model="editProduct.price" type="number" min="0" step="0.01" required></label><label class="check"><input v-model="editProduct.is_active" type="checkbox"> В меню</label><button class="primary full">Сохранить</button><button type="button" class="full" @click="editProduct=null">Отмена</button></form></div></template>
</template>

